export type PrismaPromise<T> = $Public.PrismaPromise<T>


/**
 * Model User
 * 
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model PasswordResetToken
 * 
 */
export type PasswordResetToken = $Result.DefaultSelection<Prisma.$PasswordResetTokenPayload>
/**
 * Model Document
 * 
 */
export type Document = $Result.DefaultSelection<Prisma.$DocumentPayload>
/**
 * Model GitIdentity
 * Commit author identities. Exactly one per user is the default (enforced in the service).
 */
export type GitIdentity = $Result.DefaultSelection<Prisma.$GitIdentityPayload>
/**
 * Model UserPreference
 * Cross-device user preferences (preferred agent, theme...). Device-only settings live in Electron.
 */
export type UserPreference = $Result.DefaultSelection<Prisma.$UserPreferencePayload>
/**
 * Model Organization
 * 
 */
export type Organization = $Result.DefaultSelection<Prisma.$OrganizationPayload>
/**
 * Model Role
 * 
 */
export type Role = $Result.DefaultSelection<Prisma.$RolePayload>
/**
 * Model RolePermission
 * 
 */
export type RolePermission = $Result.DefaultSelection<Prisma.$RolePermissionPayload>
/**
 * Model OrganizationMember
 * 
 */
export type OrganizationMember = $Result.DefaultSelection<Prisma.$OrganizationMemberPayload>
/**
 * Model OrganizationInvitation
 * 
 */
export type OrganizationInvitation = $Result.DefaultSelection<Prisma.$OrganizationInvitationPayload>
/**
 * Model Repository
 * A Git repository. One repository can back several projects (monorepos) via Project.sub_path.
 */
export type Repository = $Result.DefaultSelection<Prisma.$RepositoryPayload>
/**
 * Model Project
 * 
 */
export type Project = $Result.DefaultSelection<Prisma.$ProjectPayload>
/**
 * Model ProjectService
 * A runnable process definition (dev server, API, worker...). Commands are detected from package.json
 * or entered by the user; they are only ever executed by the Electron main process after validation.
 */
export type ProjectService = $Result.DefaultSelection<Prisma.$ProjectServicePayload>
/**
 * Model ProjectIssue
 * External issue reference linked to a project (we store the external id, never a copy of the issue).
 */
export type ProjectIssue = $Result.DefaultSelection<Prisma.$ProjectIssuePayload>
/**
 * Model IntegrationConnection
 * A third-party account connected through Composio. Tokens stay in Composio; only its ids are stored here.
 */
export type IntegrationConnection = $Result.DefaultSelection<Prisma.$IntegrationConnectionPayload>
/**
 * Model AgentSession
 * Metadata for an AI agent CLI session. The process + scrollback live on the device that runs it.
 */
export type AgentSession = $Result.DefaultSelection<Prisma.$AgentSessionPayload>
/**
 * Model Activity
 * 
 */
export type Activity = $Result.DefaultSelection<Prisma.$ActivityPayload>
/**
 * Model Skill
 * A user-authored skill/command/rule. Public ones are visible to the whole organization, in every
 * project; private ones are visible only to their creator (still org-scoped, still deletable by any
 * member per current policy, but never listed for anyone else).
 */
export type Skill = $Result.DefaultSelection<Prisma.$SkillPayload>
/**
 * Model SkillFavorite
 * A user's favorite skill, either a DB-backed Skill (target_kind CUSTOM, ref_id = Skill.id) or a
 * filesystem-scanned skill (target_kind SYSTEM, ref_id = its stable scan id). ref_id is polymorphic
 * on purpose, so there is no FK to Skill; SkillsService deletes orphaned favorites explicitly.
 */
export type SkillFavorite = $Result.DefaultSelection<Prisma.$SkillFavoritePayload>

